import type {HardwareEntry,HardwareFrame} from './hardware';
type Question=[string,string,string[],string, [string,string][]];
type Step=[string,string,[string,string][]];
type Entry=Omit<HardwareEntry,'practice'|'worked'> & {prompt:string,steps:Step[],checks:Question[]};
const frames=(items:[string,string][]):HardwareFrame[]=>items.map(([label,value])=>({label,value}));
const make=({prompt,steps,checks,...rest}:Entry):HardwareEntry=>({...rest,worked:{prompt,steps:steps.map(([title,reason,f])=>({title,reason,frames:frames(f)}))},practice:checks.map(([prompt,answer,options,explanation,f])=>({prompt,answer,options,explanation,hint:'Reveal the next labelled part of the diagram, then follow how it connects.',clues:frames(f)}))});
export const moreHardwareEntries:HardwareEntry[]=[
make({id:'3.1.2',title:'Follow an instruction inside the CPU',minutes:18,opening:'Imagine numbered pigeonholes holding both instructions and numbers. How does a computer find the right one, then do the right job?',mission:'Step through a fetch–decode–execute cycle.',
 sections:[['Keep instructions and data in the same memory','In Von Neumann architecture, instructions and data are stored in the same memory. RAM is working memory: it holds the programs and data being used. Each memory location has an address, like the number on a pigeonhole. Registers are small, fast storage locations inside the CPU.'],['Fetch: bring the next instruction into the CPU','The program counter (PC) holds the address of the next instruction. The address is copied to the memory address register (MAR). The address bus carries it to RAM, and a read signal travels on the control bus. The instruction returns on the data bus to the memory data register (MDR), then is copied to the current instruction register (CIR). The PC advances to the next instruction address.'],['Decode: work out what to do','The control unit (CU) decodes the instruction held in the CIR. Decode means work out which action the instruction asks for. The CU coordinates other parts of the CPU using control signals. If the instruction needs data from RAM, the address goes into the MAR and the data is fetched into the MDR.'],['Execute: carry out the action','The arithmetic logic unit (ALU) performs calculations and comparisons. The accumulator (ACC) holds intermediate results: values produced while a calculation is being worked out. Execution may calculate a value, store data or change which instruction comes next. The CPU then repeats the cycle.'],['Keep the three buses separate','A bus is a set of connections. The address bus carries addresses from the CPU to memory. The data bus carries instructions and data in either direction. The control bus carries signals, such as read and write, that coordinate the work. An address says where; data says what; a control signal says what action to take.']],
 prompt:'An instruction at address 2 says to load the value held at address 9. Address 9 contains 12.',steps:[['Fetch the instruction','PC contains 2. Copy 2 to MAR, send a read signal, and bring the instruction through MDR to CIR. PC advances to 3.',[['PC → MAR','2'],['RAM → MDR → CIR','LOAD 9'],['Next PC','3']]],['Decode LOAD','The control unit identifies LOAD as a command to bring a value from memory into the accumulator.',[['CIR','LOAD 9'],['CU action','Read address 9']]],['Execute LOAD','MAR holds 9. The data bus brings 12 from RAM to MDR; the value is then loaded into ACC.',[['MAR','9'],['MDR','12'],['ACC','12']]]],
 checks:[['The CPU needs the instruction at address 5. Which register holds that address during the memory access?','MAR',['MAR','CIR','ACC'],'The MAR holds the address being accessed. CIR holds the instruction itself, while ACC holds calculation results.',[['Need','Instruction at 5'],['Memory access','Where?'],['MAR','5']]],['RAM sends the value 20 to the CPU. Which bus carries 20?','Data bus',['Data bus','Address bus','Control bus'],'20 is the value being transferred, so it travels on the data bus.',[['Address bus','Where to read'],['Control bus','Read signal'],['Data bus','Value 20']]]],
 takeaways:['Von Neumann architecture stores instructions and data in the same memory.','PC, MAR, MDR, CIR and ACC have different roles in the fetch–decode–execute cycle.','The CU coordinates work, the ALU calculates and compares, and buses carry addresses, data or control signals.'],mistake:'The PC holds the next instruction’s address, not the instruction. The instruction being decoded is held in the CIR.',exam:'Name and explain the ALU, CU, PC, MAR, MDR, CIR and ACC. Trace fetching an instruction or data from RAM, decoding and executing it, using the address, data and control buses.',simple:'Think of a cook reading numbered recipe steps. One note says which step comes next, another holds the step being followed, and a work bowl holds the result so far. The CPU uses different registers for these different jobs.',another:'To add the value at address 8, the CPU fetches the ADD instruction into CIR. The CU decodes it, the value at address 8 is read into MDR, and the ALU adds it to ACC.',terms:['ram','register','pc','mar','mdr','cir','acc','cu','alu','bus','instruction'],preview:['Fetch from RAM','Decode in the CU','Execute with the ALU']}),
make({id:'3.1.3',title:'What makes a CPU faster?',minutes:10,opening:'Would four people always finish a job four times faster? It depends on whether they can share the work.',mission:'Compare cores, cache and clock speed.',sections:[['Share work between cores','A core is a processing unit inside a CPU. More cores can work on more tasks at once, or share a task that software can divide. If one step needs the previous step’s result, extra cores may help very little.'],['Keep frequently needed data nearby','Cache is small, fast memory in or close to the CPU. It keeps frequently used instructions and data. Getting a value from cache is faster than fetching it from RAM. A larger cache can hold more useful values, reducing slower RAM accesses when the needed values fit in it.'],['Increase the clock speed','Clock speed is the number of CPU clock cycles per second. A cycle is a timing pulse used to coordinate operations. GHz means billions of cycles per second. For otherwise comparable processors, a higher clock speed can allow more work per second. An instruction may take several cycles, and performance also depends on the program and processor design.']],
 prompt:'A photo program can process four separate photos at once. It repeatedly uses the same small set of settings.',steps:[['Look for work that can be shared','Separate photos can be processed independently, so several cores can be useful.',[['Four photos','Independent jobs'],['Four cores','Share the jobs']]],['Look for repeated data','Frequently used settings can be kept in cache, avoiding repeated trips to RAM.',[['Settings','Needed repeatedly'],['Cache','Fast access nearby']]],['Consider the timing','A higher clock speed may help each core carry out work sooner, but it does not make every program exactly twice as fast.',[['More clock cycles','More opportunities to work'],['Actual improvement','Depends on the task']]]],
 checks:[['A calculation must finish step 1 before step 2 can start. Will adding cores always make it four times faster?','No',['No','Yes'],'Dependent steps cannot simply be shared between four cores at the same time.',[['Step 1','Produces a value'],['Step 2','Needs that value'],['Order','Wait for step 1']]],['A CPU keeps fetching the same value from RAM. Which feature could keep it closer for faster access?','Cache',['Cache','A larger screen','A printer'],'Cache holds frequently needed values close to the CPU for faster access.',[['Repeated value','Needed again'],['RAM trip','Takes time'],['Cache copy','Nearby access']]]],takeaways:['Extra cores help when work can run in parallel.','Cache can reduce slower accesses to RAM.','Higher clock speed can improve performance, but the actual gain depends on the task and CPU.'],mistake:'Four cores do not guarantee four times the speed. Software must be able to share the work.',exam:'Explain how the number of cores, cache size and clock speed can affect CPU performance, linking each feature to how work is carried out.',simple:'A kitchen can have more cooks, a shelf of ingredients close by, and a faster working pace. Each helps in a different way; some recipes still need steps done in order.',another:'Four independent files may benefit from four cores. Repeatedly used data may benefit from a larger cache. A single chain of dependent calculations cannot all run at once.',terms:['core','cache','clock','ram','cpu'],preview:['Cores share tasks','Cache keeps data close','Clock sets the pace']}),
make({id:'3.1.4',title:'The commands a CPU understands',minutes:8,opening:'A calculator has a set of actions it knows how to do. A CPU also has a set of commands it can carry out.',mission:'Try commands on a small model CPU.',sections:[['A processor has an instruction set','An instruction set is the complete set of commands a CPU can process. Commands can load data, perform calculations, compare values and store results. Different CPU designs can support different instruction sets.'],['The commands are machine code','Machine code is the binary form of instructions that a CPU executes directly. The CPU design decides what each code means. The words LOAD and ADD in this activity are readable labels for invented model codes; they are not a universal code used by all processors.'],['A supported command is needed','A CPU cannot directly execute a command outside its instruction set. A program written for one processor design may need to be translated or changed for another. The key idea is the link between a supported command and its machine-code pattern.']],prompt:'A model CPU supports LOAD, ADD and STORE. It receives LOAD 5, ADD 2, then STORE.',steps:[['Load a starting value','The supported LOAD command puts 5 into the model’s working register.',[['Command','LOAD 5'],['Working value','5']]],['Add another value','ADD is supported. The model changes its working value from 5 to 7.',[['Command','ADD 2'],['Working value','5 + 2 = 7']]],['Store the result','STORE is supported and copies the result into the model’s saved result.',[['Command','STORE'],['Saved result','7']]]],checks:[['A CPU’s instruction set includes ADD but not DRAW. Which command can it execute directly?','ADD',['ADD','DRAW'],'ADD is in its instruction set. A command outside the set cannot be executed directly.',[['Supported set','ADD, LOAD, STORE'],['Candidate','ADD'],['Match','In the set']]],['A model CPU follows LOAD 8, ADD 3, STORE. What value is saved?','11',['11','8','3'],'LOAD starts with 8. ADD 3 makes 11. STORE saves that result.',[['LOAD 8','Working value: 8'],['ADD 3','8 + 3 = 11'],['STORE','Saved result: 11']]]],takeaways:['An instruction set contains all commands a CPU can process.','These commands are represented in machine code.','Different CPU designs may support different instruction sets.'],mistake:'The activity’s short binary codes are invented. A particular pattern does not mean the same command on every CPU.',exam:'Define an instruction set as the complete set of commands a CPU can process, and state that those commands are machine code.',simple:'A vending machine accepts only certain buttons and coins. In a similar way, a CPU can directly follow only commands its design supports.',another:'One model supports MULTIPLY; another supports only ADD. They have different instruction sets, even if both can eventually calculate the same answer using different steps.',terms:['instructionSet','machineCode','instruction','cpu'],preview:['Choose a command','Read its binary code','Check CPU support']}),
make({id:'3.1.5',title:'Computers inside everyday devices',minutes:9,opening:'A washing machine follows a wash cycle, but you do not use it to write an essay. Its computer has a particular job.',mission:'Find embedded systems around you.',sections:[['A computer can be part of a larger device','An embedded system is a computer built into another device to perform a dedicated function. Dedicated means it is designed for a particular job. It can receive inputs, follow stored instructions and control outputs.'],['Recognise everyday examples','Domestic appliances control washing, cooking or cooling. Cars use controllers for braking and engine functions. Security systems monitor alarms; lighting systems control lights; vending machines handle selections, payment and dispensing. The embedded computer controls part of the larger device.'],['Compare with general-purpose computers','A general-purpose computer, such as a PC or laptop, can run many different applications: writing, drawing, games and more. An embedded system focuses on its assigned function. Being small or having no screen is not the definition, and it does not have to connect to the internet.']],prompt:'A vending machine must check payment and release the selected drink.',steps:[['Identify the larger device','The vending machine contains the computer; selling drinks is its dedicated function.',[['Device','Vending machine'],['Purpose','Sell selected items']]],['Follow its input and processing','A selection and payment enter. The controller checks whether enough money has been paid.',[['Inputs','Choice + payment'],['Processing','Check the amount']]],['Follow its output','The controller tells a mechanism to release a drink. That physical action is an output.',[['Controller signal','Release selected drink'],['Output','Dispensing mechanism moves']]]],checks:[['A computer built into a car controls the brakes. What type of system is it?','Embedded system',['Embedded system','General-purpose laptop'],'It is part of a larger device and carries out the dedicated braking function.',[['Larger device','Car'],['Assigned function','Control braking'],['Type','Embedded system']]],['Which example is a general-purpose computer?','A laptop used for writing, games and drawing',['A laptop used for writing, games and drawing','A controller that only runs a wash cycle'],'The laptop runs many different applications instead of one dedicated appliance function.',[['Application 1','Writing'],['Application 2','Games and drawing'],['Purpose','Many different tasks']]]],takeaways:['An embedded system is built into a larger device for a dedicated function.','Appliances, cars, security, lighting and vending machines can contain embedded systems.','General-purpose PCs and laptops run a wide range of applications.'],mistake:'An embedded system can have a screen and network connection. Its dedicated role makes it embedded.',exam:'Describe an embedded system’s dedicated function and contrast it with a general-purpose computer, using suitable examples.',simple:'Think of a specialist tool and a toolbox. An embedded controller does an assigned job inside one device; a laptop can be used for many different jobs.',another:'A lighting controller reads a light level and switches lamps on. A PC can instead run a spreadsheet, edit a photo or play a game.',terms:['embedded','input','output'],preview:['Appliance controller','One dedicated function','Compare with a laptop']}),
make({id:'3.2.1',title:'Getting information into a computer',minutes:16,opening:'You can type a word, take a photo or scan a code. Each gives a computer different information about the world.',mission:'Choose an input device and follow what it captures.',sections:[['Input devices capture data','An input device sends data or instructions into a computer. A keyboard identifies pressed keys; an optical mouse compares images of a lit surface to track movement. A microphone changes sound vibrations into an electrical signal, which is converted into digital data. A digital camera measures light to build an image.'],['Read codes and shapes','A barcode scanner detects reflected light from bars and spaces, then decodes an identifying number. A QR scanner captures and decodes a two-dimensional code. A 2D scanner captures a flat image of a page; a 3D scanner measures points on an object’s surface to build a digital shape. Choose a device for the data needed, rather than expecting every scanner to do the same job.'],['Touch screens use different methods','A resistive screen detects pressure bringing conducting layers together. A capacitive screen detects a change in electrical capacitance: the ability to hold charge, affected by a conducting finger. An infra-red screen detects where a finger interrupts a grid of light beams. A touch screen is an input device when sensing a touch, and an output device when displaying an image.']],prompt:'A museum wants a digital model of a small statue, rather than a flat picture of it.',steps:[['Decide what data is needed','The model must describe the shape, including depth, not just colour on a flat image.',[['Required data','Three-dimensional shape'],['Flat photo alone','Not enough']]],['Choose the device','A 3D scanner measures surface points from different positions.',[['Input device','3D scanner'],['Captured data','Surface points']]],['Use the captured result','The points are combined into a digital 3D model that can be viewed and measured.',[['Measurements','Many surface points'],['Computer data','3D model']]]],checks:[['A checkout needs the product number from printed bars and spaces. Which input device fits?','Barcode scanner',['Barcode scanner','Speaker','3D printer'],'A barcode scanner reads and decodes the printed pattern into an identifying number.',[['Printed pattern','Bars + spaces'],['Needed data','Product number'],['Device','Barcode scanner']]],['A screen detects touch when pressure brings two conducting layers together. Which type is it?','Resistive',['Resistive','Capacitive','Infra-red'],'Resistive touch screens detect contact between layers caused by pressure.',[['Action','Press'],['Change','Layers touch'],['Type','Resistive']]]],takeaways:['Input devices capture data and send it into a computer.','Select a device by the data needed: keys, movement, sound, images, codes or shape.','Resistive, capacitive and infra-red touch screens detect touches in different ways.'],mistake:'A barcode usually identifies a product. Its current price is looked up in a database, rather than read as the price from the bars.',exam:'Explain why input devices are needed, how the listed devices operate and why each suits a given context. Include all three touch-screen technologies and both 2D and 3D scanners.',simple:'A computer cannot hear a voice or see a page by itself. A microphone or scanner turns something from the world into data it can work with.',another:'To capture speech, use a microphone. To copy a paper certificate, use a 2D scanner. To record the shape of a replacement part, use a 3D scanner.',terms:['input','data','sensor','barcode'],preview:['Capture something','Turn it into data','Choose the right device']}),
make({id:'3.2.2',title:'Turning results into output',minutes:16,opening:'A computer can show a picture, play a sound, print a page or move a valve. How does its result reach the world?',mission:'Follow a signal through an output device.',sections:[['Output makes a result available','An output device turns a computer result into information we can see or hear, or into a physical action. A speaker makes a cone vibrate to create sound. An actuator turns a control signal into movement or another action, such as opening a valve. A 3D printer builds a physical object layer by layer from a digital model.'],['Print a page in two different ways','An inkjet printer sprays tiny drops of liquid ink through nozzles onto paper. A laser printer uses a laser to create a charge pattern on a drum. Toner powder sticks to that pattern, transfers to paper and is fused onto it using heated rollers. Toner is powder, rather than liquid ink.'],['Control light to make an image','LCD means liquid crystal display. A screen’s liquid crystals control light from a backlight through coloured subpixels, the small colour parts of a pixel. An LED emits its own light. Large LED screens can build pixels from coloured LEDs; many consumer “LED screens” are LCD panels with LED backlights. A DLP projector uses tiny tilting mirrors to direct light through a lens. An LCD projector controls light using liquid crystal panels, then projects it through a lens.']],prompt:'A greenhouse computer decides that dry soil needs water.',steps:[['Keep the decision inside the computer','The computer processes the soil reading and decides to open a water valve.',[['Data','Soil is dry'],['Decision','Open valve']]],['Send a control signal','A control signal is sent to an actuator attached to the valve.',[['Computer output','Open command'],['Output device','Actuator']]],['Change the physical world','The actuator moves the valve so water flows. A sensor measures; an actuator acts.',[['Action','Valve opens'],['Physical result','Water flows']]]],checks:[['Which printer uses toner powder fused onto paper?','Laser printer',['Laser printer','Inkjet printer','3D printer'],'A laser printer transfers toner to paper and fixes it using heat.',[['Material','Toner powder'],['Final step','Fuse using heat'],['Device','Laser printer']]],['Which output device changes a computer signal into movement?','Actuator',['Actuator','Microphone','Temperature sensor'],'An actuator causes a physical action, such as moving a motor or valve.',[['Computer','Control signal'],['Mechanism','Motor or valve'],['Output','Movement']]]],takeaways:['Output devices present results or cause physical actions.','Inkjet, laser and 3D printers create output using different processes.','LCD and LED displays, DLP and LCD projectors, speakers and actuators suit different output needs.'],mistake:'A sensor captures a measurement as input. An actuator receives a control signal and produces a physical output.',exam:'Explain the purpose, operation and suitable use of actuators, DLP and LCD projectors, inkjet and laser printers, LED and LCD screens, speakers and 3D printers.',simple:'The CPU can work out an answer, but another device must show it, play it, print it or act on it. That is the output device’s job.',another:'To share a presentation with a class, a projector enlarges the image onto a wall. To keep a paper copy, a printer produces the page instead.',terms:['output','actuator','sensor','pixel'],preview:['Computer signal','Device does its job','Visible or physical result']}),
make({id:'3.2.3',title:'Choose a sensor for the job',minutes:14,opening:'A greenhouse needs to know when the soil is dry. Measuring the room’s noise level would not answer that question.',mission:'Match the measurement to the right sensor.',sections:[['A sensor measures a physical condition','A sensor is an input device that detects a condition in the real world and supplies measurement data. Choose it by the quantity needed. Temperature measures hot or cold; light measures light intensity; acoustic sensors detect sound; pressure measures force per unit area; an accelerometer measures changes in motion.'],['Separate similar measurements','Humidity measures water vapour in the air; moisture measures water in material such as soil. Flow measures how quickly fluid passes a point; level measures how high the contents reach. Gas sensors measure a gas concentration; pH measures how acidic or alkaline a solution is. These measurements answer different questions.'],['Detect objects and fields','Proximity sensors detect how near an object is. Infra-red sensors respond to infra-red radiation, a kind of light beyond what we can see; they can detect warm people or interrupted beams. Magnetic field sensors detect a magnetic field, for example from a magnet attached to a door. The catalogue below the selector covers all 14 required sensor types.']],prompt:'An automatic watering system must check whether the soil contains enough water.',steps:[['Name the condition','The question is about water in the soil, not water vapour in the air.',[['Material','Soil'],['Required condition','Water content']]],['Choose the measurement','Use a moisture sensor. A humidity sensor would measure air humidity instead.',[['Sensor','Moisture'],['Measured data','Water in material']]],['Use the reading','The computer can compare the moisture reading with a chosen level and decide whether watering is needed.',[['Input','Moisture reading'],['Processing','Compare with target'],['Possible output','Open water valve']]]],checks:[['Which sensor measures how quickly water passes through a pipe?','Flow',['Flow','Level','Humidity'],'Flow measures the rate of movement through the pipe. Level measures how high liquid reaches.',[['Question','How much passes each minute?'],['Quantity','Flow rate'],['Sensor','Flow']]],['A fish tank needs its acidity checked. Which sensor should be used?','pH',['pH','Pressure','Acoustic'],'A pH sensor measures how acidic or alkaline a solution is.',[['Solution','Tank water'],['Condition','Acidity / alkalinity'],['Sensor','pH']]]],takeaways:['Choose a sensor by the physical quantity it measures.','Humidity differs from moisture, and flow differs from level.','Explain why a sensor’s measurement is useful in the stated context.'],mistake:'A sensor measures a condition; it does not itself decide what a whole computer-controlled system should do.',exam:'Identify data captured by acoustic, accelerometer, flow, gas, humidity, infra-red, level, light, magnetic field, moisture, pH, pressure, proximity and temperature sensors, and justify choices in context.',simple:'Ask “What exactly do I need to find out?” A sensor is a measuring tool. You would use a thermometer for temperature, not a tool that measures sound.',another:'A fridge needs a temperature sensor to check how cold it is. A water tank needs a level sensor to check how full it is. Different questions need different measurements.',terms:['sensor','input','data','actuator'],preview:['Name the condition','Choose a sensor','Use its measurement']}),
make({id:'3.3.1',title:'RAM and ROM: what stays when power goes?',minutes:11,opening:'If you type a paragraph but do not save it, switching off can lose it. Yet the computer still knows how to start next time.',mission:'Switch the power off and compare RAM with ROM.',sections:[['Primary storage is directly accessed by the CPU','Primary storage includes RAM and ROM. It supplies instructions and data directly to the CPU. A computer needs working space for changing data and instructions, and also needs instructions that remain available when it starts.'],['RAM is the changing workspace','RAM stands for random access memory. It holds programs and data currently in use. The CPU can read from it and write to it. RAM is volatile: its contents are lost when its power is switched off. Save a document to non-volatile secondary storage if it must be kept.'],['ROM keeps essential instructions','ROM stands for read-only memory. It is non-volatile: it keeps its contents without power. It normally stores fixed instructions, including startup instructions, which the computer reads when starting. Its contents are normally not changed during everyday use. RAM and ROM serve different purposes; a computer needs both working memory and lasting startup instructions.']],prompt:'A student opens a document, types an unsaved sentence and then loses power.',steps:[['During use','The open program and working document are in RAM. Startup instructions remain in ROM.',[['RAM','Working document'],['ROM','Startup instructions']]],['Power is lost','RAM loses the unsaved working contents. ROM keeps its stored instructions.',[['RAM','Contents lost'],['ROM','Contents retained']]],['Power returns','The computer can read its startup instructions, but the unsaved sentence cannot be recovered from RAM.',[['ROM','Computer can start'],['Unsaved RAM data','Gone']]]],checks:[['Which memory loses its contents when its power is switched off?','RAM',['RAM','ROM'],'RAM is volatile; ROM is non-volatile and retains its contents.',[['Power','Switched off'],['RAM','Contents lost'],['Word','Volatile']]],['Why keep startup instructions in ROM?','They remain available without power',['They remain available without power','They disappear after each use','ROM is used only to print files'],'The startup instructions must be available when the computer is next switched on.',[['Before startup','Power was off'],['Needed','Startup instructions'],['ROM','Retains them']]]],takeaways:['Primary storage is directly accessed by the CPU.','RAM is a readable and writable, volatile workspace for programs and data in use.','ROM is non-volatile and normally stores fixed instructions, such as startup instructions.'],mistake:'An unsaved document in RAM is different from a saved copy on an SSD. RAM losing power does not erase that saved SSD copy.',exam:'Explain the roles of RAM and ROM, why both are needed, and compare volatility, normal read/write use and contents.',simple:'RAM is like a temporary work surface. ROM is like a lasting instruction card for starting the machine. Clearing the work surface does not remove the instruction card.',another:'A game’s changing score is held in RAM while playing. Startup instructions in ROM must remain even when the machine is switched off.',terms:['primary','ram','rom','volatile','secondary','cpu'],preview:['RAM: current work','ROM: startup instructions','Power off: compare']}),
make({id:'3.3.2',title:'Save it, switch off, load it again',minutes:9,opening:'You close a saved photo today and open it next week. It needs a home that keeps it when the computer is off.',mission:'Follow a file between working memory and saved storage.',sections:[['Secondary storage keeps data for later','Secondary storage is used to store programs and data more permanently. It is non-volatile, so a saved copy remains when power is switched off. Hard disk drives, SSDs, memory cards, USB flash drives and optical discs are examples.'],['Move data into primary memory for use','Secondary storage is not directly accessed by the CPU. When a saved program or file is needed, its instructions and data are transferred into primary memory, such as RAM, for processing. The diagram shows this journey rather than treating a storage drive as working RAM.'],['Saving and loading are different journeys','Saving writes a copy of working data to secondary storage. Loading brings stored data into RAM to use it. Editing a document in RAM does not automatically mean the changed version is saved. If a system offers automatic saving, it still has to write the data to storage.']],prompt:'A student saves a drawing, switches off and opens it the next day.',steps:[['Save from the workspace','Write the drawing from RAM to an SSD, a type of secondary storage.',[['RAM','Current drawing'],['Save → SSD','Copy retained']]],['Switch off','The working copy in RAM is lost, but the SSD keeps its saved copy.',[['RAM','Cleared'],['SSD','Saved drawing remains']]],['Load for another session','Copy the saved drawing into RAM so the CPU can work with it again.',[['SSD','Saved drawing'],['Load → RAM','Ready for processing']]]],checks:[['Where should a file be saved so it remains when power is off?','Secondary storage',['Secondary storage','Only in volatile RAM'],'Secondary storage retains a saved copy without power.',[['Goal','Keep after switching off'],['Needed property','Non-volatile'],['Use','Secondary storage']]],['Before a CPU processes a saved file, where is the needed data transferred?','Primary memory',['Primary memory','A printer tray','A speaker'],'Data from secondary storage is loaded into primary memory for processing.',[['Saved file','Secondary storage'],['Load','Transfer data'],['For processing','Primary memory']]]],takeaways:['Secondary storage keeps saved programs and data more permanently.','It retains data without power and is not directly accessed by the CPU.','Load data into primary memory to process it; save a copy to keep it.'],mistake:'More SSD capacity gives more room for saved files. It does not mean the computer has more physical RAM.',exam:'Explain secondary storage’s more permanent role and that it is not directly accessed by the CPU.',simple:'Keep a book on a shelf, then bring it to your desk to use it. Secondary storage is the shelf; RAM is the workspace.',another:'A saved song stays on a storage drive. When played, the needed sound data is loaded into working memory so it can be processed and sent to a speaker.',terms:['secondary','primary','ram','volatile','cpu'],preview:['Work in RAM','Save to a drive','Load it next time']}),
make({id:'3.3.3',title:'Inside magnetic, optical and solid-state storage',minutes:17,opening:'A spinning hard disk, a shiny disc and a USB drive all keep data, but they store and read it in different ways.',mission:'Open three different storage models.',sections:[['Magnetic: record states on a disk','A hard disk drive (HDD) has rotating platters coated with magnetic material. Concentric circular paths are tracks; each track is divided into sectors. A read/write head uses an electromagnet to change magnetic states when writing. When reading, the head detects those states and they are decoded as data.'],['Optical: read changes in reflected light','CDs, DVDs and Blu-ray discs are optical storage. A laser follows a track of pits and lands: tiny surface differences on a pressed disc. These change the reflected light reaching a sensor; the detected pattern is decoded into data. Do not assume a pit is always 1 and a land always 0. Recordable discs create optical changes using a writable layer.'],['Solid-state: retain electrical charge','Solid-state devices have no moving read/write parts. Flash memory uses transistors, tiny electronic switches, with control gates and floating gates. An applied voltage allows charge to be stored or removed from a floating gate. Stored charge changes how the transistor behaves, allowing data to be kept without power. NAND and NOR are arrangements used in flash memory. SSDs, SD cards and USB flash drives are examples.']],prompt:'A student compares an HDD, a DVD and a USB flash drive.',steps:[['Find the physical storage method','The HDD records magnetic states on platters divided into tracks and sectors.',[['HDD','Rotating platter'],['Write / read','Magnetic states']]],['Find how light is used','The DVD is read by detecting reflected laser light from its optical pattern.',[['DVD','Pits and lands'],['Read','Laser + light sensor']]],['Find the electronic storage method','The USB drive stores data using charge in flash-memory cells, without a moving head.',[['USB flash drive','Transistors and gates'],['Store','Retained electrical charge']]]],checks:[['Which device reads an optical pattern using a laser?','Blu-ray disc drive',['Blu-ray disc drive','USB flash drive','Magnetic hard disk drive'],'Blu-ray is optical storage, read using a laser and a light sensor.',[['Method','Reflected light'],['Reader','Laser'],['Example','Blu-ray']]],['Which storage method uses transistors and floating gates?','Flash memory',['Flash memory','Magnetic platters','Printed paper'],'Flash memory stores charge in electronic cells using transistors and gates.',[['Cell','Transistor'],['Retained state','Floating-gate charge'],['Method','Flash memory']]]],takeaways:['Magnetic HDDs use platters, tracks, sectors and read/write heads.','Optical discs use laser light and an optical pattern such as pits and lands.','Solid-state flash uses transistors and stored charge; SSD, SD and USB devices are examples.'],mistake:'Solid-state means no moving read/write parts. It does not mean the device is ROM or that stored data cannot be changed.',exam:'Describe magnetic, optical and solid-state operation, with appropriate examples. Include electromagnets, platters/tracks/sectors; lasers/pits/lands; and flash NAND/NOR, transistors, control gates and floating gates.',simple:'Data can be kept as magnetic states, as an optical pattern read with light, or as charge in electronic cells. The three models let you see what each device reads.',another:'An HDD moves a head over a rotating platter. A CD drive reads with a laser. An SD card reads electronic flash cells without spinning a disk.',terms:['magnetic','optical','flash','secondary'],preview:['Magnetise a platter','Read reflected light','Keep charge in a cell']}),
make({id:'3.3.4',title:'When RAM runs out of room',minutes:11,opening:'Your desk is full, but you need another page. You put a page you are not using on a shelf and bring the needed one to the desk.',mission:'Move pages between RAM and virtual memory.',sections:[['Divide data into pages','A page is a fixed-size block of data. Programs may need more pages than RAM can currently hold. The operating system, the software that manages the computer, can make space by moving a page that is not needed immediately out of RAM.'],['Use some secondary storage as virtual memory','Virtual memory uses space on secondary storage, such as an SSD or HDD, to hold pages outside RAM. The operating system creates or reserves this space. When a page is needed again, it is moved back into RAM. Another page may have to move out to make room.'],['Explain why it can slow work down','Virtual memory allows programs to continue when available RAM is insufficient. It does not add physical RAM. Accessing secondary storage and moving pages takes longer than using pages already in RAM, so repeated page exchanges can slow the computer.']],prompt:'RAM has room for pages A and B. A program now needs page C; page B is not currently needed.',steps:[['Spot the space problem','Both RAM spaces are occupied. C cannot be loaded without making room.',[['RAM slot 1','A'],['RAM slot 2','B'],['Needed next','C']]],['Move a page out','The operating system moves B to virtual memory on secondary storage.',[['RAM','A + free space'],['Virtual memory','B retained']]],['Bring the needed page in','Load C into the free RAM space. If B is needed later, another page exchange may be required.',[['RAM','A + C'],['Secondary storage','B waits here']]]],checks:[['Where is virtual memory space located?','On secondary storage',['On secondary storage','Inside a monitor','In extra physical RAM that appears automatically'],'Virtual memory uses space on secondary storage to hold pages outside RAM.',[['RAM','Short of room'],['Pages moved out','Need somewhere to wait'],['Virtual memory space','SSD or HDD']]],['Why can heavy use of virtual memory slow a computer?','Moving pages to and from secondary storage takes time',['Moving pages to and from secondary storage takes time','It makes the screen physically smaller','It deletes the CPU'],'Secondary-storage transfers are slower than using data already in RAM.',[['Needed page','Outside RAM'],['Extra work','Move pages'],['Effect','Longer wait']]]],takeaways:['Virtual memory uses secondary storage when available RAM is not enough.','Pages are moved between RAM and virtual memory as they are needed.','Page transfers take time; virtual memory does not increase physical RAM.'],mistake:'The CPU does not use the page on a drive as if the drive were RAM. The needed page is brought back into RAM.',exam:'Explain why virtual memory is needed, how secondary-storage space is created or reserved, and how pages move between it and RAM.',simple:'A shelf can hold work that does not fit on your desk. You still bring a page back to the desk to use it, and those trips take time.',another:'With pages X and Y in RAM, request Z. Move Y out, load Z in, then request Y again to see why repeated exchanges add delay.',terms:['virtualMemory','ram','secondary'],preview:['RAM is full','Move a page out','Bring the needed page in']}),
make({id:'3.3.5',title:'Where does a cloud file actually live?',minutes:10,opening:'Upload a photo on a laptop, then open it on a phone. The file has not floated into the sky. Where did it go?',mission:'Send a file to a remote physical server.',sections:[['A server stores the remote copy','Cloud storage keeps data on remote servers accessed over a network, usually the internet. Remote means in another location. A server is a computer providing a service to other computers. It still needs physical storage devices to hold the files.'],['Upload and download are opposite directions','Upload means send data from your device to the remote service. Download means receive data from it. After uploading, another authorised device can request the file. Being able to access a cloud service does not mean the whole file is already saved locally on every device.'],['A connection is needed for remote access','Reaching the remote copy requires a working network connection and access to the service. A file deliberately downloaded or synchronised to local storage can still be used offline. Synchronised means copies are updated to match; offline edits may need to be sent when the connection returns.']],prompt:'A student uploads a report at home and opens it on a school computer.',steps:[['Upload the report','The home device sends the report over the network to a remote server.',[['Home device','Report'],['Upload → server','Physical storage']]],['Access from another device','The school computer requests the report from the same service.',[['School computer','Request report'],['Server','Find stored copy']]],['Download the data','The server sends the file back over the network. The school computer receives it.',[['Server','Stored report'],['Download → school','Received report']]]],checks:[['What physical equipment is still needed for cloud storage?','Servers and storage devices',['Servers and storage devices','Only the user’s screen','No physical equipment'],'Cloud files are held on physical storage attached to remote servers.',[['Cloud service','Remote location'],['Computer there','Server'],['File kept on','Physical storage']]],['A file exists only on a remote server and the network is unavailable. Can it be fetched now?','No',['No','Yes'],'The device cannot reach the remote file without a connection. A previously downloaded local copy is a different case.',[['File location','Remote only'],['Connection','Unavailable'],['Fetch now','Cannot reach server']]]],takeaways:['Cloud storage is remote storage accessed over a network.','Physical servers and storage devices hold cloud data.','Uploading sends data to the service; downloading receives it.'],mistake:'A cloud file is not automatically available offline. Check whether a local copy has been downloaded or synchronised.',exam:'Explain remote access to cloud storage and why physical servers and storage devices are still needed.',simple:'Think of a locker in another building. The locker is real, but you reach it through a network instead of carrying your device to it.',another:'A phone uploads a photo to a server’s storage. A tablet later downloads it. If the tablet has not saved a copy, it needs a connection to fetch it.',terms:['cloud','network','secondary'],preview:['Upload from a device','Store on a real server','Download elsewhere']}),
make({id:'3.3.6',title:'Cloud or local storage?',minutes:10,opening:'A field trip has no internet. A group project needs shared files. Would the same storage choice suit both?',mission:'Choose storage using the situation, not a slogan.',sections:[['Local storage is close to the device','Local storage holds data on the device or locally attached storage. Files can be used without an internet connection, and access need not depend on a remote provider. Capacity is limited by the available hardware. Loss, theft or failure of a device can lose its only copy, so separate backups matter.'],['Cloud storage makes remote access easier','Cloud storage can make files available on several authorised devices and help people share work. Providers may offer backup, recovery and extra capacity. Remote access depends on the network and service. Transfers take time, and ongoing subscriptions may cost money.'],['Compare control, security and reliability','Local storage gives the owner direct control over the hardware but also responsibility for protecting and backing it up. Cloud storage places data with a provider, so access controls, privacy and provider reliability matter. Neither is automatically safe or unsafe. Compare the actual needs: offline access, sharing, capacity, cost and risk.']],prompt:'A photographer must work offline during a trip, then share selected photos with a team.',steps:[['Meet the offline need','Keep working copies on local storage so they can be accessed without internet.',[['Situation','No connection'],['Choice','Local working copies']]],['Meet the sharing need','When connected, upload selected files to a cloud service for authorised team access.',[['Situation','Several team members'],['Choice','Shared cloud copies']]],['Protect the work','Keep a separate backup and check access permissions. A single copy is vulnerable wherever it lives.',[['Risk','Loss or failure'],['Response','Backup + access controls']]]],checks:[['Which choice suits an area with no internet when a file must be opened immediately?','A local copy',['A local copy','A file stored only in the cloud'],'A local copy can be read without reaching a remote server.',[['Connection','None'],['Need','Open now'],['Useful copy','Local']]],['What is a possible disadvantage of cloud storage?','Remote access depends on a network and service',['Remote access depends on a network and service','It needs no physical storage','It cannot ever share files'],'A connection or service failure can prevent access to a remote-only file.',[['File','Remote server'],['Access route','Network + service'],['Risk','Route unavailable']]]],takeaways:['Local storage supports offline access but needs suitable hardware and backups.','Cloud storage supports remote access and sharing but depends on a network and service.','Justify choices using capacity, cost, access, control, privacy and reliability.'],mistake:'“Cloud” does not guarantee a backup of every earlier version. Recovery depends on the service and settings.',exam:'Compare cloud and local storage with advantages and disadvantages linked to a given context.',simple:'Keeping work in your bag makes it available without a connection. Keeping a shared copy in a remote service helps others access it. You can use both for different reasons.',another:'A class shares a cloud folder for teamwork. A student downloads the needed documents before travelling so they remain available offline.',terms:['cloud','secondary','network'],preview:['Offline access','Shared access','Compare the trade-offs']}),
make({id:'3.4.1',title:'The hardware that joins a network',minutes:9,opening:'A laptop needs more than an app to send data to another device. Something must connect its electronics to the network.',mission:'Connect a network interface and try sending data.',sections:[['A network needs an interface','A NIC is a network interface card or controller. It provides the hardware connection between a device and a network, preparing data for sending and receiving it through the network connection. A device needs a suitable network interface to access the network.'],['It can be built in or added','A wired NIC connects using a cable. A wireless interface sends and receives radio signals. The hardware can be integrated into the main circuit board or supplied as an additional card or adapter. An integrated NIC is still network hardware even though no separate card is visible.'],['The interface has a MAC address','A NIC is assigned a media access control (MAC) address during manufacture. It identifies that network interface. A device with separate wired and wireless interfaces can therefore have different MAC addresses for them. The next lesson opens up the address structure.']],prompt:'A desktop has no wireless interface but needs to join a wireless network.',steps:[['Identify what is missing','Software alone cannot provide the required radio hardware.',[['Required connection','Wireless'],['Missing hardware','Wireless interface']]],['Add a suitable interface','A compatible wireless adapter supplies the network interface.',[['Adapter','Wireless NIC'],['Connection method','Radio signals']]],['Send and receive','With the interface configured and connected, the device can exchange network data.',[['Device','Data'],['NIC','Network connection'],['Network','Send / receive']]]],checks:[['Can a device with no suitable network interface access a network just by opening an app?','No',['No','Yes'],'A suitable hardware interface is required to send and receive through that connection.',[['App','Requests a connection'],['Hardware interface','Missing'],['Result','Cannot connect']]],['When is a NIC assigned its manufacturer MAC address?','During manufacture',['During manufacture','Every time a document is printed','Only after opening a browser'],'The NIC is given its MAC address during manufacture.',[['Component','NIC'],['Manufacture','Address assigned'],['Address type','MAC']]]],takeaways:['A NIC provides hardware needed for network access.','Interfaces can be wired or wireless, integrated or added separately.','A NIC is assigned a MAC address during manufacture.'],mistake:'A NIC does not have to be a visible removable card. Many computers have integrated network controllers.',exam:'Explain why a NIC is required for network access and state that its MAC address is assigned at manufacture.',simple:'A doorway connects a room to a corridor. A network interface is the hardware route that lets data enter and leave a device over a network.',another:'A laptop can contain both a wired network controller and a wireless controller. Each is an interface and can have its own MAC address.',terms:['nic','mac','network'],preview:['Choose an interface','Make the connection','Send and receive']}),
make({id:'3.4.2',title:'Read a MAC address',minutes:10,opening:'A network interface needs an identifier. A MAC address gives its identity in a compact pattern of hexadecimal digits.',mission:'Separate the manufacturer and serial parts.',sections:[['Identify a network interface','MAC stands for media access control. A MAC address identifies a network interface and is used for delivery on the local network. A NIC is assigned a MAC address at manufacture. It is different from an IP address allocated for the device’s place on a network.'],['Read the usual format','A usual MAC address has 48 bits: six bytes, with eight bits per byte. It is commonly written as six pairs of hexadecimal digits, separated by colons or hyphens. Each hexadecimal digit shows four bits, so 12 hexadecimal digits show 48 bits. A–F stand for the values 10–15.'],['Separate the two parts','In the common manufacturer-assigned 48-bit format, the first three bytes identify the manufacturer. The last three bytes provide the interface’s serial code within that manufacturer’s allocation. This is the syllabus model. Modern devices can also use software-set or private MAC addresses; do not assume a displayed address can never change.']],prompt:'Read the example MAC address 00:1A:2B:3C:4D:5E.',steps:[['Count the groups','There are six groups. Each pair of hex digits represents one byte.',[['Groups','00 · 1A · 2B · 3C · 4D · 5E'],['Total','6 bytes = 48 bits']]],['Read the manufacturer part','In the usual manufacturer-assigned format, take the first three groups.',[['First 3 bytes','00:1A:2B'],['Meaning','Manufacturer identifier']]],['Read the serial part','The last three groups identify the interface within the manufacturer’s allocation.',[['Last 3 bytes','3C:4D:5E'],['Meaning','Serial code']]]],checks:[['In the usual format, which part of 00:1A:2B:3C:4D:5E identifies the manufacturer?','00:1A:2B',['00:1A:2B','3C:4D:5E','Only 5E'],'The first three bytes form the manufacturer identifier in this format.',[['Full address','00:1A:2B:3C:4D:5E'],['Take','First three pairs'],['Manufacturer','00:1A:2B']]],['How many hexadecimal digits are in six pairs?','12',['12','6','48'],'Two hexadecimal digits per pair, multiplied by six pairs, gives 12 digits.',[['One pair','2 hex digits'],['Six pairs','6 × 2'],['Total','12 hex digits']]]],takeaways:['A MAC address identifies a network interface.','A usual 48-bit MAC address is written as six pairs of hexadecimal digits.','The common manufacturer-assigned format contains a manufacturer identifier and an interface serial code.'],mistake:'A MAC address identifies an interface. An IP address serves a different addressing role on a network.',exam:'Explain the purpose and usual hexadecimal structure of a MAC address, including manufacturer identification and a serial code.',simple:'Think of a product code split into “who made it” and “which item”. The two labelled halves help you read the usual manufacturer-assigned MAC format.',another:'00:1A:2B:10:20:30 and 00:1A:2B:10:20:31 share the same manufacturer part but have different serial parts.',terms:['mac','nic','hexadecimal','byte','ip'],preview:['Six pairs of hex digits','Manufacturer part','Interface serial part']}),
make({id:'3.4.3',title:'Give a device an IP address',minutes:13,opening:'A letter needs a destination address. Data sent across networks also needs an address so it can reach the right place.',mission:'Compare IPv4 and IPv6, then reconnect a device.',sections:[['An IP address locates a device on a network','An IP address is allocated to a device on a network. It is used to direct data towards its destination. Unlike a manufacturer-assigned MAC address identifying an interface, an IP address relates to its network connection and can change when it joins a different network.'],['Compare IPv4 and IPv6','IPv4 uses 32 bits, usually written as four denary groups separated by dots. Each group represents eight bits and ranges from 0 to 255. IPv6 uses 128 bits. A full IPv6 address is written as eight groups of four hexadecimal digits separated by colons. More bits give IPv6 a far larger supply of possible addresses.'],['Choose static or dynamic allocation','A static IP address stays assigned to a device rather than being automatically changed between allocations. A dynamic address is allocated from available addresses and can change when allocated again; it does not have to change at every connection. A router can allocate addresses on a local network. Use an address valid for that network and avoid assigning the same address to two devices on it.']],prompt:'A school device has IPv4 address 192.0.2.25. It reconnects using dynamic allocation.',steps:[['Read the address format','Four denary groups, separated by dots, identify the usual IPv4 notation.',[['Address','192.0.2.25'],['Format','4 groups × 8 bits = 32 bits']]],['Consider the allocation method','Dynamic allocation can give an available address on reconnection, which may be different.',[['Before','192.0.2.25'],['Possible new allocation','192.0.2.26']]],['Contrast a static assignment','A static assignment keeps the allocated address unless deliberately changed.',[['Static assignment','192.0.2.25'],['Reconnect','Same assigned address']]]],checks:[['Which version uses 128-bit addresses?','IPv6',['IPv6','IPv4'],'IPv6 has 128-bit addresses; IPv4 has 32-bit addresses.',[['IPv4','32 bits'],['IPv6','128 bits'],['Larger address space','IPv6']]],['A device may receive a different address when allocated one again. Which method is this?','Dynamic',['Dynamic','Static'],'A dynamic address can change on a new allocation. It is not guaranteed to change every time.',[['Allocation','From available addresses'],['Reconnect','May get a different one'],['Method','Dynamic']]]],takeaways:['An IP address is allocated on a network and directs data towards a destination.','IPv4 uses 32 bits; IPv6 uses 128 bits and a much larger address space.','Static addresses stay assigned; dynamic addresses can change on a new allocation.'],mistake:'Dynamic does not mean the address changes every second, or must change every time a device reconnects.',exam:'Explain IP address purpose and allocation, static and dynamic addresses, and differences between IPv4 and IPv6 in bit length, notation and address capacity.',simple:'Your network address is like an address for where you can currently be reached. The manufacturer label on the network interface is a different kind of identifier.',another:'192.0.2.40 is IPv4: four denary groups. 2001:0DB8:0000:0000:0000:0000:0000:0040 is full IPv6: eight hexadecimal groups.',terms:['ip','ipv4','ipv6','mac','hexadecimal','denary'],preview:['IPv4: 32 bits','IPv6: 128 bits','Static or dynamic?']}),
make({id:'3.4.4',title:'Route data to another network',minutes:11,opening:'A road junction sends traffic towards the right destination. A router chooses where network data should go next.',mission:'Send a packet through a router to its destination.',sections:[['Connect different networks','A router connects networks and forwards packets between them. A packet is a small unit of data sent over a network. The router reads its destination IP address, checks routing information and chooses a suitable next route. This can be a step towards the destination rather than a direct connection to the final device.'],['Connect a local network to the internet','A local network connects devices in a limited area, such as a home or school. A router can connect it to the internet, a network of networks. Not every packet needs to leave the local network; two devices on the same local network can communicate without routing through another network.'],['Allocate local addresses','A router can provide automatic IP address allocation for devices joining its local network. This gives them usable addresses so data can be directed correctly. Address allocation and packet forwarding are different functions, even when the same router does both.']],prompt:'A school computer sends a packet to a server on another network.',steps:[['Identify the destination','The packet includes the server’s destination IP address.',[['Packet header','Destination IP'],['Target','Server on another network']]],['Choose the route','The router examines the destination and selects a next route using its routing information.',[['Router reads','Destination address'],['Routing choice','Towards server network']]],['Forward the packet','The router forwards the packet along that route. Other routers may handle later steps.',[['Next network','Packet forwarded'],['Final destination','May need more hops']]]],checks:[['Two computers are on the same local network. Must their messages travel across the internet?','No, they can communicate within the local network',['No, they can communicate within the local network','Yes, every message must leave the local network','Only if both computers have the same IP address'],'Communication within the same local network does not have to pass through another network.',[['Computer A','On the school network'],['Computer B','On the same school network'],['Message route','Can stay within this local network']]],['What can a router do for a device joining its local network?','Allocate an IP address',['Allocate an IP address','Replace all RAM','Print the device’s files'],'A router can provide automatic allocation of local IP addresses.',[['New device','Joins local network'],['Needs','Usable network address'],['Router service','IP allocation']]]],takeaways:['A router connects networks and forwards packets towards their destinations.','It examines destination IP addresses and chooses a suitable next route.','A router can connect a local network to the internet and allocate local IP addresses.'],mistake:'A router need not connect directly to the final destination. It can forward a packet to another router on the route.',exam:'Explain routing towards a destination, allocation of IP addresses, and connecting a local network to the internet.',simple:'At a road junction, a sign points you towards your destination, even if it is many roads away. A router similarly chooses the next route for a packet.',another:'A home router sends a request towards an internet server using its destination IP. It can also allocate a local IP address to a newly connected laptop.',terms:['router','ip','network','packet','packetHeader','nic'],preview:['Read destination IP','Choose the next route','Forward the packet']})
];
